     const rule_info_t *rule, int verdict, uint64_t timestamp, 
     uint64_t counter, const mmt_array_t * const trace ){
     int new_val = random(15, 8);
     int is_string = 0;
     // replace_dicom_attribute(PROTO_DICOM, DICOM_PDU_TYPE, &new_val, is_string); 
     replace_dicom_attribute(701, 1, &new_val, is_string);
     forward_packet();
}
